import React, { Component } from 'react';
import {
    CButton, CCard, CCardBody, CCol, CContainer, CInput, CInputGroup,
    CInputGroupAppend, CInputGroupPrepend, CInputGroupText, CRow
} from '@coreui/react';
import MaterialReactTable from 'material-react-table';
import {
    requestHeaderGETWithAuth,
    requestHeaderPOSTWithAuth,
    requestHeaderPUTWithAuth,
    requestHeaderDELETEWithAuth,
} from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { Logger, reloadPage } from '../../Utils/Utils';
import { Loading } from '../Statuses/Statuses';
import { BACKEND_NEXUS_APP_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';
import StatusModal from '../Modals/StatusModal';
import FailureModal from '../Modals/FailureModal';

import Select from 'react-select';

const FILE_NAME = "MediaData.js";

const API_BASE = BACKEND_NEXUS_APP_BASE_URL + '/v1/media-data';

const emptyForm = {
    id: null,          // null => create mode, non-null => edit mode
    link: '',
    fileName: '',
    creators: [],
    additionDate: '',  // "added on" date (yyyy-MM-dd); optional
    rating: '',
    toBeTrimmed: false,  // optional boolean
    tenantId: '',
};

class MediaData extends Component {

    constructor(props) {
        super(props);
        this.state = {
            isLoaded: false,
            mediaList: [],
            // tenant dropdown options
            tenants: [],
            tenantsLoadError: false,
            // creator multi-select options (fetched MediaDataCreator rows)
            creatorsList: [],
            creatorsLoadError: false,
            // free-text search across link / fileName / creator + pagination
            searchTerm: '',
            page: 1,
            size: 10,
            totalPages: 0,
            totalElements: 0,
            // add / edit form
            form: { ...emptyForm },
            formError: null,
            // modals
            loadingModalVisible: false,
            loadingModalState: 0,
            failureModalVisible: false,
        };
    }

    componentDidMount() {
        document.title = "Media Data";
        this.fetchTenants();
        this.fetchCreators();
        this.loadAll();
    }

    // ---------- tenants (searchable dropdown) ----------

    fetchTenants = () => {
        const userData = getUserDataFromLocalStorage();
        const url = BACKEND_NEXUS_APP_BASE_URL + '/v1/tenants';
        const reqData = { page: 1, size: 100 };

        fetch(url, requestHeaderPOSTWithAuth(JSON.stringify(reqData), userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "fetchTenants", "SUCCESS", "result", result);
            const content = (result && result.data && result.data.content) || [];
            this.setState({ tenants: content, tenantsLoadError: false });
        })
        .catch(error => {
            Logger(FILE_NAME, "fetchTenants", "ERROR", "error", error);
            this.setState({ tenantsLoadError: true });
        });
    }

    // Build react-select options from the fetched tenants list.
    tenantOptions = () => this.state.tenants.map(t => ({
        value: String(t.id),
        label: t.urn ? `${t.name} (${t.urn})` : `${t.name} [#${t.id}]`,
    }));

    // ---------- creators (searchable multi-select) ----------

    // The list endpoint returns the full array of MediaDataCreator rows directly in `data`.
    fetchCreators = () => {
        const userData = getUserDataFromLocalStorage();
        const url = BACKEND_NEXUS_APP_BASE_URL + '/v1/media-data-creator/list?offset=0';

        fetch(url, requestHeaderGETWithAuth(userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) return this.handleUnauthorized();
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            if (!result) return;
            Logger(FILE_NAME, "fetchCreators", "SUCCESS", "result", result);
            this.setState({ creatorsList: result.data || [], creatorsLoadError: false });
        })
        .catch(error => {
            Logger(FILE_NAME, "fetchCreators", "ERROR", "error", error);
            this.setState({ creatorsLoadError: true });
        });
    }

    // Build react-select options from the fetched creators list.
    creatorSelectOptions = () => this.state.creatorsList.map(c => ({
        value: String(c.id),
        label: c.link ? `${c.name} (${c.link})` : c.name,
    }));

    // Resolve a creator id to a readable label (creator name; falls back to the raw id).
    creatorLabel = (id) => {
        const match = this.state.creatorsList.find(c => String(c.id) === String(id));
        if (!match) return id;
        return match.name;
    }

    // Reload the background reference resources (creators + tenants) without touching the
    // media list or current page/search. Both fetches run concurrently in the background.
    reloadResources = () => {
        Logger(FILE_NAME, "reloadResources", "START", "", "");
        this.fetchTenants();
        this.fetchCreators();
    }

    // ---------- helpers ----------

    isEditing = () => this.state.form.id != null;

    nullIfBlank = (value) => {
        const trimmed = (value || '').trim();
        return trimmed === '' ? null : trimmed;
    }

    // ---------- clipboard ----------

    // Paste clipboard text into a form field.
    pasteFromClipboard = (field) => {
        if (!navigator.clipboard || !navigator.clipboard.readText) {
            this.setState({ failureModalVisible: true });
            return;
        }
        navigator.clipboard.readText()
            .then(text => {
                Logger(FILE_NAME, "pasteFromClipboard", field, "text", text);
                this.handleFormChange(field, text);
            })
            .catch(error => {
                Logger(FILE_NAME, "pasteFromClipboard", field, "error", error);
                this.setState({ failureModalVisible: true });
            });
    }

    // Copy an arbitrary value to the clipboard.
    copyToClipboard = (value) => {
        const text = value == null ? '' : String(value);
        if (!navigator.clipboard || !navigator.clipboard.writeText) {
            this.setState({ failureModalVisible: true });
            return;
        }
        navigator.clipboard.writeText(text)
            .then(() => Logger(FILE_NAME, "copyToClipboard", "SUCCESS", "text", text))
            .catch(error => {
                Logger(FILE_NAME, "copyToClipboard", "ERROR", "error", error);
                this.setState({ failureModalVisible: true });
            });
    }

    handleUnauthorized = () => {
        this.setState({ loadingModalVisible: false, failureModalVisible: true });
        setTimeout(() => { logoutProcedureForLocalStorage(); reloadPage(); }, 500);
    }

    // ---------- read: list + search ----------

    // Paginated free-text search (POST /search with PaginatedSearchRequest).
    // A blank/short term makes the backend return all active rows, paginated.
    fetchList = () => {
        const { page, size, searchTerm } = this.state;
        const userData = getUserDataFromLocalStorage();
        const url = API_BASE + '/search';
        const reqData = { page, size, search: searchTerm ? searchTerm.trim() : null };

        Logger(FILE_NAME, "fetchList", "REQUEST", "reqData", reqData);
        this.setState({ isLoaded: false });

        fetch(url, requestHeaderPOSTWithAuth(JSON.stringify(reqData), userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) return this.handleUnauthorized();
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "fetchList", "RESULT", "result", result);
            const pageData = (result && result.data) || {};
            this.setState({
                isLoaded: true,
                mediaList: pageData.content || [],
                totalPages: pageData.totalPages || 0,
                totalElements: pageData.totalElements != null ? pageData.totalElements : 0,
            });
        })
        .catch(error => {
            Logger(FILE_NAME, "fetchList", "ERROR", "error", error);
            this.setState({ isLoaded: true, failureModalVisible: true });
        });
    }

    // "List all / refresh" — reset to page 1 with an empty search term.
    loadAll = () => {
        this.setState({ searchTerm: '', page: 1 }, () => this.fetchList());
    }

    handleSearch = (event) => {
        if (event) event.preventDefault();
        this.setState({ page: 1 }, () => this.fetchList());
    }

    handlePrevPage = () => {
        if (this.state.page > 1) {
            this.setState({ page: this.state.page - 1 }, () => this.fetchList());
        }
    }

    handleNextPage = () => {
        if (this.state.page < this.state.totalPages) {
            this.setState({ page: this.state.page + 1 }, () => this.fetchList());
        }
    }

    // ---------- create / update ----------

    handleFormChange = (field, value) => {
        this.setState(prevState => ({ form: { ...prevState.form, [field]: value } }));
    }

    resetForm = () => {
        this.setState({ form: { ...emptyForm }, formError: null });
    }

    startEditing = (item) => {
        this.setState({
            form: {
                id: item.id,
                link: item.link || '',
                fileName: item.fileName || '',
                creators: Array.isArray(item.creators) ? item.creators.map(Number) : [],
                additionDate: item.additionDate || '',
                rating: item.rating != null ? String(item.rating) : '',
                toBeTrimmed: !!(item.metadata && item.metadata.toBeTrimmed === true),
                tenantId: item.tenantId != null ? String(item.tenantId) : '',
            }
        });
        window.scrollTo({ top: 0, behavior: 'smooth' });
    }

    // Navigate to the slideshow player for a media record (single file or album folder).
    openSlideshow = (item) => {
        Logger(FILE_NAME, "openSlideshow", "", "id", item.id);
        this.props.history.push('/media-data/' + item.id + '/slideshow');
    }

    handleSubmit = (event) => {
        event.preventDefault();
        const { form } = this.state;

        const link = (form.link || '').trim();
        // tenantId is optional: when left blank the backend derives it from the link
        // (via the tenant's base_domains match).
        const tenantIdRaw = form.tenantId == null ? '' : String(form.tenantId).trim();
        if (link === '') {
            this.setState({ formError: 'Link is required.' });
            return;
        }

        const ratingRaw = form.rating == null ? '' : String(form.rating).trim();
        let rating = null;
        if (ratingRaw !== '') {
            if (!/^-?\d+$/.test(ratingRaw)) {
                this.setState({ formError: 'Rating must be a whole number (negatives allowed).' });
                return;
            }
            rating = Number(ratingRaw);
        }

        const payload = {
            link,
            fileName: this.nullIfBlank(form.fileName),
            creators: Array.isArray(form.creators) ? form.creators : [],
            additionDate: this.nullIfBlank(form.additionDate),
            rating,
            // toBeTrimmed lives inside the MediaData.metadata jsonb object (MediaMetadata) on the backend.
            metadata: { toBeTrimmed: form.toBeTrimmed === true },
            tenantId: tenantIdRaw === '' ? null : Number(tenantIdRaw),
        };

        const editing = this.isEditing();
        let url = API_BASE + '/save';
        let requestOptions = requestHeaderPOSTWithAuth(JSON.stringify(payload), getUserDataFromLocalStorage().authToken);
        if (editing) {
            payload.id = form.id;
            url = API_BASE + '/update';
            requestOptions = requestHeaderPUTWithAuth(JSON.stringify(payload), getUserDataFromLocalStorage().authToken);
        }

        Logger(FILE_NAME, "handleSubmit", editing ? "UPDATE" : "CREATE", "request", { url, payload });
        this.setState({ formError: null, loadingModalVisible: true, loadingModalState: 0 });

        fetch(url, requestOptions)
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) return this.handleUnauthorized();
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "handleSubmit", "RESULT", "result", result);
            if (!result) return;
            if (result.code === 1001) {
                // success
                this.setState({ loadingModalState: 1 });
                setTimeout(() => {
                    this.setState({ loadingModalVisible: false, loadingModalState: 0 });
                    this.resetForm();
                    this.loadAll();
                }, 600);
            } else {
                // backend business error (e.g. duplicate link, or tenant could not be resolved
                // from the link) — surface the exact backend message in the form error banner and
                // scroll it into view so it isn't missed.
                this.setState({
                    loadingModalVisible: false,
                    loadingModalState: 0,
                    formError: result.message || 'Save failed (backend rejected the request).',
                });
                window.scrollTo({ top: 0, behavior: 'smooth' });
            }
        })
        .catch(error => {
            Logger(FILE_NAME, "handleSubmit", "ERROR", "error", error);
            this.setState({ loadingModalVisible: false, failureModalVisible: true });
        });
    }

    // ---------- delete ----------

    handleDelete = (item) => {
        if (!window.confirm('Delete media record #' + item.id + '?')) return;

        const userData = getUserDataFromLocalStorage();
        const url = API_BASE + '/' + item.id;

        this.setState({ loadingModalVisible: true, loadingModalState: 0 });

        fetch(url, requestHeaderDELETEWithAuth(null, userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) return this.handleUnauthorized();
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "handleDelete", "SUCCESS", "result", result);
            this.setState({ loadingModalState: 1 });
            setTimeout(() => {
                this.setState({ loadingModalVisible: false, loadingModalState: 0 });
                // if we were editing the row we just deleted, clear the form
                if (this.state.form.id === item.id) this.resetForm();
                this.loadAll();
            }, 600);
        })
        .catch(error => {
            Logger(FILE_NAME, "handleDelete", "ERROR", "error", error);
            this.setState({ loadingModalVisible: false, failureModalVisible: true });
        });
    }

    // ---------- render ----------

    // Small inline "copy to clipboard" button used in list cells.
    renderCopyButton = (value) => (
        <CButton
            color="link"
            size="sm"
            className="p-0 ml-1"
            title="Copy to clipboard"
            style={{ verticalAlign: 'baseline' }}
            onClick={() => this.copyToClipboard(value)}
        >
            📋
        </CButton>
    )

    // MaterialReactTable column definitions for the results list.
    // Column order: ID, Actions, File Name, Link, then a combined Creator / Rating / Tenant column.
    getColumns = () => ([
        {
            accessorKey: 'id',
            header: 'ID',
            size: 70,
            Cell: ({ row }) => {
                const { id, fileName } = row.original;
                // Link straight to the slideshow player, opening in a new tab (HashRouter path).
                return fileName ? (
                    <a
                        href={'#/media-data/' + id + '/slideshow'}
                        target="_blank"
                        rel="noopener noreferrer"
                        title="Open play screen in a new tab"
                    >
                        {id}
                    </a>
                ) : id;
            },
        },
        {
            accessorKey: 'actions',
            header: 'Actions',
            size: 160,
            enableSorting: false,
            enableColumnFilter: false,
            Cell: ({ row }) => (
                <span style={{ whiteSpace: 'nowrap' }}>
                    <CButton
                        color="success"
                        size="lg"
                        className="mr-2"
                        style={{ fontSize: '1.15rem', fontWeight: 700, padding: '10px 20px' }}
                        title={row.original.fileName ? 'Play / view media' : 'No file to play'}
                        disabled={!row.original.fileName}
                        onClick={() => this.openSlideshow(row.original)}
                    >
                        ▶️ Play
                    </CButton>
                    <CButton color="primary" size="sm" className="mr-2" onClick={() => this.startEditing(row.original)}>✏️ Edit</CButton>
                    <CButton color="danger" size="sm" onClick={() => this.handleDelete(row.original)}>🗑️ Delete</CButton>
                </span>
            ),
        },

        {
            // Combined Creators / Rating / Tenant / Added On / To Be Trimmed column.
            id: 'creatorRatingTenant',
            header: 'Creators / Rating / Tenant / Added On / Trim',
            size: 280,
            enableSorting: false,
            Cell: ({ row }) => {
                const { creators, rating, tenantId, additionDate, metadata } = row.original;
                const toBeTrimmed = !!(metadata && metadata.toBeTrimmed === true);
                const creatorNames = Array.isArray(creators) && creators.length > 0
                    ? creators.map(id => this.creatorLabel(id)).join(', ')
                    : '';
                return (
                    <div style={{ lineHeight: '1.5' }}>
                        <div>
                            <strong>🧑‍🎨 Creators:</strong>{' '}
                            {creatorNames ? <>{creatorNames}{this.renderCopyButton(creatorNames)}</> : '—'}
                        </div>
                        <div>
                            <strong>⭐ Rating:</strong>{' '}
                            {rating != null ? <>{rating}{this.renderCopyButton(rating)}</> : '—'}
                        </div>
                        <div>
                            <strong>🏢 Tenant:</strong>{' '}
                            {tenantId != null ? <>{this.tenantLabel(tenantId)}{this.renderCopyButton(tenantId)}</> : '—'}
                        </div>
                        <div>
                            <strong>📅 Added On:</strong>{' '}
                            {additionDate ? <>{additionDate}{this.renderCopyButton(additionDate)}</> : '—'}
                        </div>
                        <div>
                            <strong>✂️ To Be Trimmed:</strong>{' '}
                            {toBeTrimmed === true ? '✅ Yes' : 'No'}
                        </div>
                    </div>
                );
            },
        },

        {
            accessorKey: 'Details',
            header: 'File Name',
            size: 180,
            Cell: ({ row }) => {
                const { link, fileName } = row.original;
                return (
                    <div style={{ lineHeight: '1.5' }}>
                        <div>
                            <strong>🔗 Link:</strong>{' '}
                            <span style={{ display: 'inline-flex', alignItems: 'center', maxWidth: '320px' }}>
                                <a href={link} target="_blank" rel="noopener noreferrer" style={{ wordBreak: 'break-all' }}>{link}</a>
                                        {this.renderCopyButton(link)}
                            </span>
                        </div>
                        <div>
                            <strong>⭐ File Name:</strong>{' '}
                            {fileName != null ? <>{fileName}{this.renderCopyButton(fileName)}</> : '—'}
                        </div>
                    </div>
                )
            }
        },
    ])

    // Resolve a tenant id to a readable label (tenant name only; falls back to the raw id).
    tenantLabel = (tenantId) => {
        const match = this.state.tenants.find(t => String(t.id) === String(tenantId));
        if (!match) return tenantId;
        return match.name;
    }

    render() {
        const { isLoaded, mediaList, form, searchTerm } = this.state;
        const editing = this.isEditing();

        return (
            <div>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
                    <h2>🎬 Media Data ({this.state.totalElements})</h2>
                    <div style={{ display: 'flex', gap: '8px' }}>
                        <CButton color="primary" onClick={() => this.props.history.push('/media-data-creator')} title="Open Media Data Creators page">🧑‍🎨 Media Data Creators</CButton>
                        <CButton color="info" onClick={this.reloadResources} title="Reload creators & tenants in the background">♻️ Reload resources</CButton>
                        <CButton color="secondary" onClick={this.loadAll} title="Refresh / List all">🔄 List all</CButton>
                    </div>
                </div>

                {this.state.tenantsLoadError && (
                    <div style={{ padding: '12px 16px', marginBottom: '16px', backgroundColor: '#f8d7da', border: '1px solid #f5c6cb', borderRadius: '4px', color: '#721c24' }}>
                        ⚠️ Failed to load tenants list. Please check your connection and <CButton color="link" style={{ padding: 0, color: '#721c24', textDecoration: 'underline' }} onClick={() => this.fetchTenants()}>retry</CButton>.
                    </div>
                )}

                {this.state.creatorsLoadError && (
                    <div style={{ padding: '12px 16px', marginBottom: '16px', backgroundColor: '#f8d7da', border: '1px solid #f5c6cb', borderRadius: '4px', color: '#721c24' }}>
                        ⚠️ Failed to load creators list. Please check your connection and <CButton color="link" style={{ padding: 0, color: '#721c24', textDecoration: 'underline' }} onClick={() => this.fetchCreators()}>retry</CButton>.
                    </div>
                )}

                {/* ---------- Add / Edit form ---------- */}
                <CContainer className="mb-4">
                    <CCard className="p-3">
                        <CCardBody>
                            <h4>{editing ? '✏️ Edit Media #' + form.id : '➕ Add Media'}</h4>
                            <hr />
                            {this.state.formError && (
                                <div style={{ padding: '10px 14px', marginBottom: '14px', backgroundColor: '#f8d7da', border: '1px solid #f5c6cb', borderRadius: '4px', color: '#721c24' }}>
                                    ⚠️ {this.state.formError}
                                </div>
                            )}
                            <form onSubmit={this.handleSubmit}>
                                <CRow>
                                    {/* Left column: Link and File Name stacked one below another. */}
                                    <CCol md="6">
                                        <label><strong>Link *</strong></label>
                                        <CInputGroup className="mb-3">
                                            <CInputGroupPrepend>
                                                <CInputGroupText>🔗</CInputGroupText>
                                            </CInputGroupPrepend>
                                            <CInput
                                                placeholder="https://..."
                                                type="text"
                                                value={form.link}
                                                onChange={(e) => this.handleFormChange('link', e.target.value)}
                                                required
                                            />
                                            <CInputGroupAppend>
                                                <CButton color="info" type="button" title="Paste from clipboard" onClick={() => this.pasteFromClipboard('link')}>📋</CButton>
                                            </CInputGroupAppend>
                                        </CInputGroup>
                                        <label><strong>File Name</strong></label>
                                        <CInputGroup className="mb-3">
                                            <CInputGroupPrepend>
                                                <CInputGroupText>📄</CInputGroupText>
                                            </CInputGroupPrepend>
                                            <CInput
                                                placeholder="optional"
                                                type="text"
                                                value={form.fileName}
                                                onChange={(e) => this.handleFormChange('fileName', e.target.value)}
                                            />
                                            <CInputGroupAppend>
                                                <CButton color="info" type="button" title="Paste from clipboard" onClick={() => this.pasteFromClipboard('fileName')}>📋</CButton>
                                            </CInputGroupAppend>
                                        </CInputGroup>
                                    </CCol>
                                    {/* Right column: Tenant and Creators stacked. */}
                                    <CCol md="6">
                                        <label><strong>Tenant</strong> <small style={{ color: '#888' }}>(optional — auto-detected from link)</small></label>
                                        <div className="mb-3">
                                            <Select
                                                value={this.tenantOptions().find(o => o.value === String(form.tenantId)) || null}
                                                onChange={(choice) => this.handleFormChange('tenantId', choice ? choice.value : '')}
                                                options={this.tenantOptions()}
                                                isClearable={true}
                                                placeholder="Search tenant..."
                                                styles={{ control: (base) => ({ ...base, minHeight: '38px' }) }}
                                            />
                                        </div>
                                        <label><strong>Creators</strong> <small style={{ color: '#888' }}>(optional, multiple)</small></label>
                                        <div className="mb-3">
                                            <Select
                                                isMulti
                                                value={this.creatorSelectOptions().filter(o => form.creators.map(String).includes(o.value))}
                                                onChange={(choices) => this.handleFormChange('creators', (choices || []).map(o => Number(o.value)))}
                                                options={this.creatorSelectOptions()}
                                                isClearable={true}
                                                placeholder="Search creators..."
                                                styles={{ control: (base) => ({ ...base, minHeight: '38px' }) }}
                                            />
                                        </div>
                                    </CCol>
                                </CRow>
                                <CRow>
                                    <CCol md="6">
                                        <label><strong>Rating</strong></label>
                                        <CInputGroup className="mb-3">
                                            <CInputGroupPrepend>
                                                <CInputGroupText>⭐</CInputGroupText>
                                            </CInputGroupPrepend>
                                            <CInput
                                                placeholder="optional whole number (negatives allowed)"
                                                type="number"
                                                step="1"
                                                value={form.rating}
                                                onChange={(e) => this.handleFormChange('rating', e.target.value)}
                                            />
                                        </CInputGroup>
                                    </CCol>
                                    <CCol md="6">
                                        <label><strong>Added On</strong> <small style={{ color: '#888' }}>(optional)</small></label>
                                        <CInputGroup className="mb-3">
                                            <CInputGroupPrepend>
                                                <CInputGroupText>📅</CInputGroupText>
                                            </CInputGroupPrepend>
                                            <CInput
                                                type="date"
                                                value={form.additionDate}
                                                onChange={(e) => this.handleFormChange('additionDate', e.target.value)}
                                            />
                                        </CInputGroup>
                                    </CCol>
                                </CRow>
                                <CRow>
                                    <CCol md="6">
                                        <div className="mb-3" style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                                            <input
                                                id="toBeTrimmed"
                                                type="checkbox"
                                                checked={form.toBeTrimmed === true}
                                                onChange={(e) => this.handleFormChange('toBeTrimmed', e.target.checked)}
                                            />
                                            <label htmlFor="toBeTrimmed" className="mb-0"><strong>✂️ To Be Trimmed</strong> <small style={{ color: '#888' }}>(optional)</small></label>
                                        </div>
                                    </CCol>
                                </CRow>
                                <hr />
                                <div style={{ display: 'flex', gap: '12px' }}>
                                    <CButton color="success" type="submit" className="px-4">
                                        {editing ? '💾 Update' : '➕ Save'}
                                    </CButton>
                                    <CButton color="secondary" type="button" onClick={this.resetForm}>
                                        {editing ? 'Cancel edit' : 'Clear'}
                                    </CButton>
                                </div>
                            </form>
                        </CCardBody>
                    </CCard>
                </CContainer>

                {/* ---------- Search (free-text over link / file name / creator) ---------- */}
                <CContainer className="mb-3">
                    <CCard className="p-3">
                        <CCardBody>
                            <h5>🔍 Search</h5>
                            <form onSubmit={this.handleSearch}>
                                <CRow className="align-items-end">
                                    <CCol md="9">
                                        <label>Search link, file name or creator (min 3 chars)</label>
                                        <CInput
                                            type="text"
                                            placeholder="type to search across link / file name / creator..."
                                            value={searchTerm}
                                            onChange={(e) => this.setState({ searchTerm: e.target.value })}
                                        />
                                    </CCol>
                                    <CCol md="3">
                                        <CButton color="primary" type="submit" className="mr-2">Search</CButton>
                                        <CButton color="secondary" type="button" onClick={this.loadAll}>Clear</CButton>
                                    </CCol>
                                </CRow>
                            </form>
                        </CCardBody>
                    </CCard>
                </CContainer>

                {/* ---------- Results table ---------- */}
                {!isLoaded ? <Loading /> : (
                    <>
                        <MaterialReactTable
                            initialState={{ density: 'compact' }}
                            columns={this.getColumns()}
                            data={mediaList}
                            enablePagination={false}
                            enableEditing={false}
                        />
                        <CContainer className="mt-3">
                            <CRow className="justify-content-center align-items-center">
                                <CCol md="6" className="text-center">
                                    <CButton color="secondary" disabled={this.state.page <= 1} onClick={this.handlePrevPage}>← Prev</CButton>
                                    &nbsp;&nbsp;
                                    <span>
                                        Page <strong>{this.state.page}</strong> of <strong>{this.state.totalPages}</strong>
                                        &nbsp;({this.state.totalElements} total)
                                    </span>
                                    &nbsp;&nbsp;
                                    <CButton color="secondary" disabled={this.state.page >= this.state.totalPages} onClick={this.handleNextPage}>Next →</CButton>
                                </CCol>
                            </CRow>
                        </CContainer>
                    </>
                )}

                <StatusModal visible={this.state.loadingModalVisible} loadingModalState={this.state.loadingModalState} />
                <FailureModal visible={this.state.failureModalVisible} />
            </div>
        );
    }
}

export default MediaData;
